import React from 'react';
import Card from '../../components/Card';

const ReceptionistDashboard = () => {
  return (
    <div className="p-6">
      <h1 className="text-3xl font-bold mb-6">Receptionist Dashboard</h1>
      <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
        <Card>
          <h3 className="text-xl font-semibold mb-2">Register Patient</h3>
          <p className="text-gray-600">Register new patients in the system</p>
        </Card>
        <Card>
          <h3 className="text-xl font-semibold mb-2">Book Appointment</h3>
          <p className="text-gray-600">Schedule appointments for patients</p>
        </Card>
      </div>
    </div>
  );
};

export default ReceptionistDashboard;
